insert into "amasas"."reference_queries" select * from jsonb_populate_recordset(null::"amasas"."reference_queries", $seed$[{"query_id":"q3_migration_drivers","sql_text":"select year as 集計年, birth as 出生, student as 就学卒業, employment as 就職, job_relocation as 転勤, job_change as 転職転業, marriage_divorce as 結婚離婚, housing as 住宅, retirement as 退職家族事情, other as その他, accompany as 同伴者, death as 死亡, (birth+student+employment+job_relocation+job_change+marriage_divorce+housing+retirement+other+accompany+death) as 純増減合計\nfrom amasas.life_stage_trends where code_name = '純増減数' order by year desc limit 5","question_ja":"人口の増減は何が要因?","description_ja":"直近年のライフステージ別純増減の分解。出典: 住民生活課","guardrail_notes_ja":"単年で断定せず直近5年の傾向で語る。事由別は一桁が多い"},{"query_id":"q4_furusato_summary","sql_text":"select a.year as 集計年, a.tax_payment as 寄付金額_円,\n  (select string_agg(category_code_name || '(' || value || '円)', ' / ' order by value desc)\n   from amasas.furusato_top5_categories t\n   where t.year = a.year and t.code_name = '金額') as 上位カテゴリ\nfrom amasas.furusato_donations_annual a order by a.year desc limit 5","question_ja":"ふるさと納税の状況は?","description_ja":"年次推移+最新年のカテゴリ上位。出典: 海士町役場","guardrail_notes_ja":"金額と件数を混同しない(code_nameフィルタ必須)。カテゴリ上位はデータのある年のみ表示される"},{"query_id":"q5_kpi_progress","sql_text":"select strategy_period as 期, basic_goal as 基本目標,\n  count(*) filter (where target_met) as 達成,\n  count(*) filter (where target_met = false) as 未達,\n  count(*) filter (where target_met is null) as 未集計\nfrom amasas.v_strategy_kpi_progress\ngroup by strategy_period, basic_goal order by strategy_period, basic_goal","question_ja":"総合戦略のKPIは進捗している?","description_ja":"政策別の達成/未達/未集計。未集計はゼロではない","guardrail_notes_ja":"未集計(NULL)を必ず「未集計」と表現しゼロや未達と混同しない。第3期(2025-)は大半が未集計。達成判定は方針(増加/減少)を考慮済み"},{"query_id":"q6_elderly_function","sql_text":"select categorized_code_name as 分類, code_name as 区分, sum(amacho_all) as 人数\nfrom amasas.elderly_function_decline_by_category\nwhere categorized_code_name <> '全て'\ngroup by categorized_code_name, code_name\nhaving sum(amacho_all) >= 10\norder by 分類, 区分","question_ja":"高齢者の生活機能の状況は?","description_ja":"分類別の低下傾向(2023年、回答者ベース)。出典: 健康福祉課","guardrail_notes_ja":"回答者ベースで全高齢者ではない。2023年単年のみ。n<10のセルは表示しない(除外した旨を明示)。「全て」分類は合計行のため除外済み"},{"query_id":"q1_population_structure","sql_text":"select year as 集計年, month as 集計月, sum(population) as 総人口,\n  sum(population) filter (where age_group_ja in ('0-4歳','5-9歳','10-14歳')) as 年少人口_0_14,\n  sum(population) filter (where age_group_ja not in ('0-4歳','5-9歳','10-14歳','65-69歳','70-74歳','75-79歳','80-84歳','85-89歳','90歳以上')) as 生産年齢人口_15_64,\n  sum(population) filter (where age_group_ja in ('65-69歳','70-74歳','75-79歳','80-84歳','85-89歳','90歳以上')) as 高齢人口_65以上,\n  round(100.0 * sum(population) filter (where age_group_ja in ('65-69歳','70-74歳','75-79歳','80-84歳','85-89歳','90歳以上')) / sum(population), 1) as 高齢化率_pct\nfrom amasas.v_population_long\nwhere (year, month) = (select year, month from amasas.v_population_long order by year desc, month desc limit 1)\ngroup by year, month","question_ja":"海士町の人口構造は?","description_ja":"最新年の総人口・年齢3区分・高齢化率。出典: 住民生活課・住民基本台帳","guardrail_notes_ja":"住民基本台帳ベースであり国勢調査とは一致しない旨を必ず付す。人口テーブルは年2時点(1月/10月)持ちのためmonth指定必須"},{"query_id":"q2_district_population","sql_text":"select district_ja as 地区, sum(population) as 人口,\n  round(100.0 * sum(population) filter (where age_group_ja in ('65-69歳','70-74歳','75-79歳','80-84歳','85-89歳','90歳以上')) / nullif(sum(population),0), 1) as 高齢化率_pct\nfrom amasas.v_population_long\nwhere (year, month) = (select year, month from amasas.v_population_long order by year desc, month desc limit 1)\ngroup by district_ja having sum(population) >= 10 order by 人口 desc","question_ja":"地区別の人口・高齢化は?","description_ja":"最新年の地区別人口と高齢化率。小地区はnが小さい","guardrail_notes_ja":"人口10人未満の地区はhavingで除外済み。除外した旨を回答に明示。性別・年齢クロスまで掘る場合もn<10断定禁止"},{"query_id":"q7_population_trend","sql_text":"select year as 年, sum(population) as 総人口,\n  round(100.0 * sum(population) filter (where age_group_ja in ('65-69歳','70-74歳','75-79歳','80-84歳','85-89歳','90歳以上')) / sum(population), 1) as 高齢化率_pct,\n  round(100.0 * sum(population) filter (where age_group_ja in ('15-19歳','20-24歳','25-29歳','30-34歳')) / sum(population), 1) as 若年比率_15_34_pct\nfrom amasas.v_population_long where month = 1\ngroup by year order by year","question_ja":"人口の推移は?(高齢化・若年層の動き)","description_ja":"各年1月時点の総人口・高齢化率・若年比率の年次推移。水準と傾向の両方が読める","guardrail_notes_ja":"各年1月時点で統一。水準(高齢化率が全国より高い)と傾向(比率の変化)を区別して伝える。傾向の解釈(若返り等の表現)は断定せずデータの記述に留める"}]$seed$::jsonb);
