-- AMASAS data layer: row data + foreign keys (added last, after load).
-- Rows are reconstructed type-safely from JSON via jsonb_populate_recordset.
-- FK defs at the end reference amasas objects unqualified → set search_path.
set search_path to amasas, public;


alter table "amasas"."data_dictionary" add constraint "data_dictionary_table_name_fkey" FOREIGN KEY (table_name) REFERENCES datasets(table_name);
alter table "amasas"."data_cards" add constraint "data_cards_table_name_fkey" FOREIGN KEY (table_name) REFERENCES datasets(table_name);
alter table "knowledge"."town_facts" add constraint "town_facts_measure_key_fkey" FOREIGN KEY (measure_key) REFERENCES knowledge.measures(measure_key);
alter table "knowledge"."involvement_paths" add constraint "involvement_paths_pillar_no_fkey" FOREIGN KEY (pillar_no) REFERENCES knowledge.strategy_pillars(pillar_no);
alter table "knowledge"."map_assets" add constraint "map_assets_doc_ref_fkey" FOREIGN KEY (doc_ref) REFERENCES knowledge.source_registry(source_key);
